if not hasattr(ctrl, 'reset'): errors.append('reset method')
if not hasattr(ctrl, 'compute'): errors.append('compute method')
ctrl.reset()
out = ctrl.compute(error=1.0, dt=0.1)
if not isinstance(out, (int, float)): errors.append('compute returns float')
print(f'  PASS: methods exist, compute returned {out:.4f}')

# Proportional response
ctrl = module.PIDController(kp=2.0, ki=0.0, kd=0.0)
ctrl.reset()
