ctrl.reset()
out2 = ctrl.compute(error=2.0, dt=0.1)
if not (abs(out2 / out1 - 2.0) < 0.5 or abs(out2 - out1 * 2) < 1.0):
    errors.append(f'proportional: out1={out1}, out2={out2}')
else: print(f'  PASS: proportional response out1={out1:.2f}, out2={out2:.2f}')

# Integral accumulation
ctrl = module.PIDController(kp=0.0, ki=1.0, kd=0.0)
ctrl.reset()
out1 = ctrl.compute(error=1.0, dt=0.1)
out2 = ctrl.compute(error=1.0, dt=0.1)
out3 = ctrl.compute(error=1.0, dt=0.1)
if not (out3 > out1): errors.append(f'integral: {out1}, {out2}, {out3}')
