{"command": "cd /home/liangfeng/git/hermes-agent/benchmark/skillsbench/tasks/adaptive-cruise-control && python3 -c "
import pandas as pd, yaml, os, subprocess, shutil, numpy as np

cwd = os.getcwd()
errors = []

# Load simulation data
sim = pd.read_csv(os.path.join(cwd, 'simulation_results.csv'))
sensor = pd.read_csv(os.path.join(cwd, 'sensor_data.csv'))

# ============================================================
# TestSpeedControl
# ============================================================
print('=== TestSpeedControl ===')
cruise = sim[sim['time'] <= 30.0]

# Rise time (10% to 90% of 30)
t10_series = cruise[cruise['ego_speed'] >= 3.0]['time']
t90_series = cruise[cruise['ego_speed'] >= 27.0]['time']
if len(t10_series) > 0 and len(t90_series) > 0:
    t10 = t10_series.min()
    t90 = t90_series.min()
    rise_time = t90 - t10
    print(f'  Rise time: {rise_time:.2f}s (must be < 10s)')
    if rise_time >= 10.0: errors.append(f'Rise time {rise_time:.2f}s >= 10s')
    else: print(f'  PASS: rise time < 10s')
else: errors.append('Speed thresholds not reached')

# Overshoot < 5% (max < 31.5 m/s)
max_cruise_speed = cruise['ego_speed'].max()
print(f'  Max cruise speed: {max_cruise_speed:.3f} m/s (must be < 31.5)')
if max_cruise_speed >= 31.5: errors.append(f'Overshoot: max speed {max_cruise_speed} >= 31.5')
else: print(f'  PASS: overshoot < 5%')

# Steady-state error < 0.5 m/s at t=25-30s
ss = sim[(sim['time'] >= 25.0) & (sim['time'] <= 30.0)]
ss_error = abs(30.0 - ss['ego_speed'].mean())
print(f'  Steady-state error: {ss_error:.3f} m/s (must be < 0.5)')
if ss_error >= 0.5: errors.append(f'Steady-state error {ss_error:.3f} >= 0.5')
else: print(f'  PASS: steady-state error < 0.5 m/s')

# ============================================================
# TestDistanceControl
# ============================================================
print('=== TestDistanceControl ===')
follow = sim[(sim['time'] >= 50.0) & (sim['time'] <= 60.0)]
follow = follow[follow['mode'] == 'follow']
follow = follow[follow['distance_error'].notna() & (follow['distance_error'] != '')]
if len(follow) >= 5:
    dist_errors = pd.to_numeric(follow['distance_error'], errors='coerce').abs()
    mean_error = dist_errors.mean()
    print(f'  Mean distance error (50-60s): {mean_error:.3f} m (must be < 2m)')
    if mean_error >= 2.0: errors.append(f'Distance error {mean_error:.3f} >= 2.0')
    else: print(f'  PASS: mean distance error < 2m')
else:
    print(f'  SKIP: only {len(follow)} follow samples in 50-60s')

# Distance never drops below 90% of safe distance
follow2 = sim[(sim['time'] >= 30.0) & (sim['time'] <= 60.0)]
follow2 = follow2[follow2['mode'] == 'follow']
follow2 = follow2[follow2['distance'].notna() & (follow2['distance'] != '')]
if len(follow2) >= 5:
    distances = pd.to_numeric(follow2['distance'], errors='coerce')
    safe_distances = follow2['ego_speed'] * 1.5 + 10.0
    min_allowed = safe_distances * 0.9
    all_ok = (distances >= min_allowed).all()
    violations = (distances < min_allowed).sum()
    print(f'  Distance violations: {violations} (must be 0)')
    if not all_ok: errors.append(f'{violations} distance violations')
    else: print(f'  PASS: all distances >= 90% of safe distance')
else:
    print(f'  SKIP: only {len(follow2)} follow samples')

# ============================================================
# TestSafety
# ============================================================
print('=== TestSafety ===')

# Min distance >= 5m
dist = sim[sim['distance'].notna() & (sim['distance'] != '')]
if len(dist) > 0:
    min_d = pd.to_numeric(dist['distance'], errors='coerce').min()
    print(f'  Min distance: {min_d:.3f} m (must be >= 5)')
    if min_d < 5.0: errors.append(f'Min distance {min_d:.3f} < 5.0')
    else: print(f'  PASS: min distance >= 5m')

# Emergency mode triggered
has_emergency = 'emergency' in sim['mode'].unique()
print(f'  Emergency mode: {\"triggered\" if has_emergency else \"NOT triggered\"}')
if not has_emergency: errors.append('Emergency mode not triggered')
else: print(f'  PASS: emergency mode triggered')

# In emergency: accel < 0
emergency = sim[sim['mode'] == 'emergency']
if len(emergency) > 0:
    if not all(emergency['acceleration_cmd'] < 0):
        errors.append('Emergency accel not all negative')
    else: print(f'  PASS: emergency braking (all accel < 0)')

# TTC < 3.0 in emergency
ttc_data = emergency[emergency['ttc'].notna() & (emergency['ttc'] != '')]
if len(ttc_data) > 0:
    ttc_vals = pd.to_numeric(ttc_data['ttc'], errors='coerce').dropna()
    all_under = all(ttc_vals < 3.0)
    if not all_under:
        errors.append(f'Emergency TTC >= 3.0: {ttc_vals.max():.2f}')
    else: print(f'  PASS: emergency TTC < 3.0 (max {ttc_vals.max():.2f})')

# Acceleration limits
max_accel = sim['acceleration_cmd'].max()
min_accel = sim['acceleration_cmd'].min()
print(f'  Acceleration range: [{min_accel:.3f}, {max_accel:.3f}]')
if max_accel > 3.01: errors.append(f'Max accel {max_accel} > 3.01')
if min_accel < -8.01: errors.append(f'Min accel {min_accel} < -8.01')
print(f'  PASS: acceleration within [-8.0, 3.0]' if max_accel <= 3.01 and min_accel >= -8.01 else '  FAIL')

# Speed non-negative
if sim['ego_speed'].min() < 0: errors.append(f'Negative ego speed: {sim[\"ego_speed\"].min()}')
else: print(f'  PASS: ego_speed >= 0')

# ============================================================
# TestScenario
# ============================================================
print('=== TestScenario ===')

# Starts at rest
first_speed = sim.iloc[0]['ego_speed']
print(f'  Initial speed: {first_speed} (must be < 1.0)')
